#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/shm.h>
#include <sys/ipc.h>
#include <unistd.h>

#define SHM_SIZE 1024  /* 1KB shared memory segment */
#define SHM_KEY 1234

int main(void) {
    int shmid;
    char *shm_ptr;
    const char *data = "Hello from Shared Memory!";

    /* 1. Get/Create a shared memory segment ID */
    shmid = shmget(SHM_KEY, SHM_SIZE, IPC_CREAT | 0666);
    if (shmid == -1) {
        perror("shmget failed");
        return EXIT_FAILURE;
    }

    /* 2. Attach the segment to the process's address space (shmat) */
    /* shmaddr=NULL lets the system choose the address; shmflg=0 for read/write */
    shm_ptr = shmat(shmid, NULL, 0);
    if (shm_ptr == (void *) -1) {
        perror("shmat failed");
        /* Clean up segment if attach fails */
        shmctl(shmid, IPC_RMID, NULL);
        return EXIT_FAILURE;
    }

    printf("Segment attached at address: %p\n", shm_ptr);

    /* 3. Write data to the shared memory */
    strncpy(shm_ptr, data, SHM_SIZE - 1);
    shm_ptr[SHM_SIZE - 1] = '\0';
    printf("Data written: %s\n", shm_ptr);

    /* 4. Detach the shared memory segment (shmdt) */
    if (shmdt(shm_ptr) == -1) {
        perror("shmdt failed");
        /* Continue to cleanup */
    }

    /* 5. Mark the segment for destruction. It is destroyed when all processes detach. */
    if (shmctl(shmid, IPC_RMID, NULL) == -1) {
        perror("shmctl (IPC_RMID) failed");
        return EXIT_FAILURE;
    }

    printf("Segment detached and marked for destruction.\n");

    return EXIT_SUCCESS;
}
